import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import dayjs from 'dayjs'
import store2 from 'store2'

export const DEFAULT_FIELD_SCHEMA = [
  {
    id: 'f_name',
    key: 'name',
    label: '名称',
    type: 'text',
    required: true,
    system: true,
    defaultValue: ''
  },
  {
    id: 'f_icon',
    key: 'iconText',
    label: '图标文字',
    type: 'text-limited',
    maxLength: 1,
    system: true,
    defaultValue: '',
    hint: '留空时自动取名称首字'
  },
  {
    id: 'f_color',
    key: 'color',
    label: '颜色',
    type: 'color',
    system: true,
    defaultValue: '#8f7955'
  },
  {
    id: 'f_note',
    key: 'note',
    label: '备注',
    type: 'textarea',
    maxLength: 2000,
    defaultValue: ''
  }
]

export const getTypeDefault = (type) => {
  const defaults = {
    'text': '',
    'text-limited': '',
    'color': '#8f7955',
    'textarea': '',
    'switch': false,
    'number': 0,
    'select': '',
    'rating': 0
  }
  return Object.prototype.hasOwnProperty.call(defaults, type) ? defaults[type] : ''
}

export function useCalendarApp() {
  const currentYear = ref(new Date().getFullYear())
  const currentMonth = ref(1)
  const viewMode = ref('year')
  const selectedEventId = ref(null)

  const isEditMode = ref(false)
  const isClearMode = ref(false)
  const showAddDialog = ref(false)
  const showEditDialog = ref(false)
  const showDayDetailDialog = ref(false)
  const showEventsManageDialog = ref(false)
  const showSchemaConfigDialog = ref(false)
  const searchKeyword = ref('')
  const selectedDayInfo = ref({
    year: 0,
    month: 0,
    day: 0,
    events: []
  })

  const fieldSchema = ref(DEFAULT_FIELD_SCHEMA.map(f => ({ ...f })))

  const createEventForm = () => {
    const form = {}
    fieldSchema.value.forEach(field => {
      form[field.key] = field.defaultValue !== undefined ? field.defaultValue : getTypeDefault(field.type)
    })
    return form
  }

  const newEventForm = ref(createEventForm())
  const editEventForm = ref({ id: '', ...createEventForm() })

  const events = ref([])
  const dayEvents = ref({})

  const predefineColors = [
    '#ff4500', '#ff8c00', '#ffd700', '#90ee90',
    '#00ced1', '#1e90ff', '#c71585', '#ff69b4',
    '#ba55d3', '#9370db', '#3cb371', '#b8860b',
    '#cd5c5c', '#4682b4', '#d2691e', '#dc143c',
    '#00fa9a', '#4169e1', '#ff1493', '#00bfff'
  ]

  const getDefaultIconText = (name) => (name || '').trim().charAt(0)

  const normalizeIconText = (iconText, name) => {
    const normalized = (iconText || '').trim().charAt(0)
    return normalized || getDefaultIconText(name)
  }

  const normalizeEvent = (event) => {
    const normalized = { ...event }
    normalized.iconText = normalizeIconText(event.iconText, event.name)
    fieldSchema.value.forEach(field => {
      if (normalized[field.key] === undefined) {
        normalized[field.key] = field.defaultValue !== undefined ? field.defaultValue : getTypeDefault(field.type)
      }
    })
    return normalized
  }

  const normalizeEvents = (eventList) => (Array.isArray(eventList) ? eventList.map(normalizeEvent) : [])

  const loadData = () => {
    const savedSchema = store2.get('calendar_field_schema')
    if (savedSchema && Array.isArray(savedSchema)) {
      fieldSchema.value = savedSchema
    }
    const savedEvents = store2.get('calendar_events')
    const savedDayEvents = store2.get('calendar_day_events')
    if (savedEvents) {
      events.value = normalizeEvents(savedEvents)
    }
    if (savedDayEvents) {
      dayEvents.value = savedDayEvents
    }
    newEventForm.value = createEventForm()
  }

  const saveData = () => {
    store2.set('calendar_events', events.value)
    store2.set('calendar_day_events', dayEvents.value)
    store2.set('calendar_field_schema', fieldSchema.value)
  }

  const updateFieldSchema = (newSchema) => {
    fieldSchema.value = newSchema
    newEventForm.value = createEventForm()
    saveData()
    ElMessage.success('属性配置已保存')
  }

  const eventCounts = computed(() => {
    return events.value.map((event) => {
      let count = event.id == '1769158131096' ? 56 : event.id == '1769158154545' ? 3 : 0
      Object.values(dayEvents.value).forEach((eventIds) => {
        if (eventIds.includes(event.id)) {
          count += 1
        }
      })
      return { id: event.id, count }
    })
  })

  const getEventCount = (eventId) => {
    const found = eventCounts.value.find((ec) => ec.id === eventId)
    return found ? found.count : 0
  }

  const filteredEvents = computed(() => {
    if (!searchKeyword.value.trim()) {
      return events.value
    }
    const keyword = searchKeyword.value.toLowerCase()
    const textFieldKeys = fieldSchema.value
      .filter(f => ['text', 'text-limited', 'textarea'].includes(f.type))
      .map(f => f.key)
    return events.value.filter((event) =>
      textFieldKeys.some(key => event[key] && String(event[key]).toLowerCase().includes(keyword))
    )
  })

  const toggleEditMode = () => {
    isClearMode.value = false
    isEditMode.value = !isEditMode.value
    if (!isEditMode.value) {
      selectedEventId.value = null
    }
  }

  const openEditEvent = (eventId) => {
    const event = events.value.find((item) => item.id === eventId)
    if (!event) {
      return
    }
    const form = { id: event.id }
    fieldSchema.value.forEach(field => {
      let val = event[field.key]
      if (val === undefined) {
        val = field.defaultValue !== undefined ? field.defaultValue : getTypeDefault(field.type)
      }
      if (field.key === 'iconText') {
        val = normalizeIconText(val, event.name)
      }
      form[field.key] = val
    })
    editEventForm.value = form
    showEditDialog.value = true
  }

  const handleManageEventClick = (eventId) => {
    isClearMode.value = false
    if (isEditMode.value) {
      openEditEvent(eventId)
      return
    }
    selectEvent(eventId)
    showEventsManageDialog.value = false
  }

  const toggleClearMode = () => {
    isClearMode.value = !isClearMode.value
    if (isClearMode.value) {
      isEditMode.value = false
      selectedEventId.value = null
    }
  }

  const handleEventClick = (eventId) => {
    isClearMode.value = false
    if (isEditMode.value) {
      openEditEvent(eventId)
      return
    }
    selectEvent(eventId)
  }

  const addEvent = (formData = newEventForm.value) => {
    isClearMode.value = false
    if (!formData.name?.trim()) {
      return
    }
    const event = { id: Date.now().toString() }
    fieldSchema.value.forEach(field => {
      let val = formData[field.key]
      if (val === undefined) {
        val = field.defaultValue !== undefined ? field.defaultValue : getTypeDefault(field.type)
      }
      if (field.key === 'iconText') {
        val = normalizeIconText(val, formData.name)
      } else if (['text', 'text-limited', 'textarea'].includes(field.type)) {
        val = (val || '').trim()
      }
      event[field.key] = val
    })
    events.value.push(event)
    newEventForm.value = createEventForm()
    showAddDialog.value = false
    saveData()
  }

  const saveEditEvent = (formData = editEventForm.value) => {
    const event = events.value.find((item) => item.id === formData.id)
    if (event) {
      fieldSchema.value.forEach(field => {
        let val = formData[field.key]
        if (val === undefined) {
          val = field.defaultValue !== undefined ? field.defaultValue : getTypeDefault(field.type)
        }
        if (field.key === 'iconText') {
          val = normalizeIconText(val, formData.name)
        } else if (['text', 'text-limited', 'textarea'].includes(field.type)) {
          val = (val || '').trim()
        }
        event[field.key] = val
      })
      saveData()
    }
    showEditDialog.value = false
    isEditMode.value = !isEditMode.value
    isClearMode.value = false
  }

  const confirmDeleteEvent = (formData = editEventForm.value) => {
    deleteEvent(formData.id)
    showEditDialog.value = false
    isEditMode.value = !isEditMode.value
    isClearMode.value = false
  }

  const deleteEvent = (eventId) => {
    events.value = events.value.filter((event) => event.id !== eventId)
    Object.keys(dayEvents.value).forEach((dateKey) => {
      dayEvents.value[dateKey] = dayEvents.value[dateKey].filter((id) => id !== eventId)
      if (dayEvents.value[dateKey].length === 0) {
        delete dayEvents.value[dateKey]
      }
    })
    if (selectedEventId.value === eventId) {
      selectedEventId.value = null
    }
    saveData()
  }

  const selectEvent = (eventId) => {
    selectedEventId.value = selectedEventId.value === eventId ? null : eventId
  }

  const changeYear = (delta) => {
    currentYear.value += delta
  }

  const enterMonth = (month) => {
    currentMonth.value = month
    viewMode.value = 'month'
  }

  const exitMonth = () => {
    viewMode.value = 'year'
  }

  const getMonthDays = (month) => {
    const firstDay = dayjs(`${currentYear.value}-${month}-1`)
    const daysInMonth = firstDay.daysInMonth()
    const startWeekday = firstDay.day()
    const days = []
    for (let i = 0; i < startWeekday; i += 1) {
      days.push(null)
    }
    for (let i = 1; i <= daysInMonth; i += 1) {
      days.push(i)
    }
    return days
  }

  const hasColor = (year, month, day) => {
    const dateKey = `${year}-${month}-${day}`
    const eventIds = dayEvents.value[dateKey] || []
    return eventIds.length > 0
  }

  const getDayEventNames = (year, month, day) => {
    const dateKey = `${year}-${month}-${day}`
    const eventIds = dayEvents.value[dateKey] || []
    if (eventIds.length === 0) {
      return ''
    }
    const eventNames = eventIds
      .map((id) => events.value.find((event) => event.id === id)?.name)
      .filter(Boolean)
    return eventNames.join('、')
  }

  const getMonthEventTypes = (year, month) => {
    const firstDay = dayjs(`${year}-${month}-1`)
    const daysInMonth = firstDay.daysInMonth()
    const uniqueEventIds = new Set()
    for (let day = 1; day <= daysInMonth; day += 1) {
      const dateKey = `${year}-${month}-${day}`
      const eventIds = dayEvents.value[dateKey] || []
      eventIds.forEach((id) => uniqueEventIds.add(id))
    }
    return uniqueEventIds.size
  }

  const getMonthEventCount = (year, month) => {
    const firstDay = dayjs(`${year}-${month}-1`)
    const daysInMonth = firstDay.daysInMonth()
    let totalCount = 0
    for (let day = 1; day <= daysInMonth; day += 1) {
      const dateKey = `${year}-${month}-${day}`
      const eventIds = dayEvents.value[dateKey] || []
      totalCount += eventIds.length
    }
    return totalCount
  }

  const getTotalEventTypes = () => {
    const uniqueEventIds = new Set()
    Object.values(dayEvents.value).forEach((eventIds) => {
      eventIds.forEach((id) => uniqueEventIds.add(id))
    })
    return uniqueEventIds.size
  }

  const getTotalEventCount = () => {
    let totalCount = 56 + 3;
    Object.values(dayEvents.value).forEach((eventIds) => {
      totalCount += eventIds.length
    })
    return totalCount
  }

  const getYearEventCount = (year) => {
    let totalCount = 0
    const yearPrefix = `${year}-`
    Object.entries(dayEvents.value).forEach(([dateKey, eventIds]) => {
      if (dateKey.startsWith(yearPrefix)) {
        totalCount += eventIds.length
      }
    })
    return totalCount
  }

  const getDayStyle = (year, month, day) => {
    const dateKey = `${year}-${month}-${day}`
    const eventIds = dayEvents.value[dateKey] || []
    if (eventIds.length === 0) {
      return {}
    }
    const colors = eventIds
      .map((id) => events.value.find((event) => event.id === id)?.color)
      .filter(Boolean)
    if (colors.length === 0) {
      return {}
    }
    if (colors.length === 1) {
      return {
        backgroundColor: colors[0]
      }
    }
    const colorStops = colors.map((color, index, arr) => {
      const segmentSize = 100 / arr.length
      const start = index * segmentSize
      const end = (index + 1) * segmentSize
      const gradientRange = 4
      if (index === 0) {
        return `${color} 0%, ${color} ${end - gradientRange}%`
      }
      if (index === arr.length - 1) {
        return `${color} ${start + gradientRange}%, ${color} 100%`
      }
      return `${color} ${start + gradientRange}%, ${color} ${end - gradientRange}%`
    }).join(', ')
    return {
      background: `linear-gradient(135deg, ${colorStops})`
    }
  }

  const toggleDayEvent = (year, month, day) => {
    const dateKey = `${year}-${month}-${day}`
    if (isClearMode.value) {
      if (dayEvents.value[dateKey]) {
        delete dayEvents.value[dateKey]
        saveData()
        ElMessage.success('已清除该日期的颜色')
      }
      return
    }
    if (selectedEventId.value) {
      if (!dayEvents.value[dateKey]) {
        dayEvents.value[dateKey] = []
      }
      const eventIndex = dayEvents.value[dateKey].indexOf(selectedEventId.value)
      if (eventIndex > -1) {
        dayEvents.value[dateKey].splice(eventIndex, 1)
        if (dayEvents.value[dateKey].length === 0) {
          delete dayEvents.value[dateKey]
        }
      } else {
        dayEvents.value[dateKey].push(selectedEventId.value)
      }
      saveData()
      return
    }
    if (!isEditMode.value && !isClearMode.value) {
      showDayDetail(year, month, day)
    }
  }

  const showDayDetail = (year, month, day) => {
    const dateKey = `${year}-${month}-${day}`
    const eventIds = dayEvents.value[dateKey] || []
    const eventDetails = eventIds
      .map((id) => events.value.find((event) => event.id === id))
      .filter(Boolean)
    selectedDayInfo.value = {
      year,
      month,
      day,
      events: eventDetails
    }
    showDayDetailDialog.value = true
  }

  const exportData = () => {
    const data = {
      events: events.value,
      dayEvents: dayEvents.value,
      fieldSchema: fieldSchema.value,
      exportDate: new Date().toISOString(),
      version: '1.2'
    }
    const dataStr = JSON.stringify(data, null, 2)
    const blob = new Blob([dataStr], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `calendar-data-${dayjs().format('YYYY-MM-DD')}.json`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
    ElMessage.success('数据导出成功')
  }

  const importData = (event) => {
    const file = event.target.files?.[0]
    if (!file) {
      return
    }
    const reader = new FileReader()
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target.result)
        if (!data.events || !data.dayEvents) {
          ElMessage.error('数据格式错误')
          return
        }
        if (data.fieldSchema && Array.isArray(data.fieldSchema)) {
          fieldSchema.value = data.fieldSchema
        }
        events.value = normalizeEvents(data.events)
        dayEvents.value = data.dayEvents
        newEventForm.value = createEventForm()
        saveData()
        ElMessage.success('数据导入成功')
      } catch (error) {
        ElMessage.error('导入失败：文件格式错误')
        console.error(error)
      }
    }
    reader.readAsText(file)
    event.target.value = ''
  }

  onMounted(() => {
    loadData()
  })

  return {
    currentYear,
    currentMonth,
    viewMode,
    selectedEventId,
    isEditMode,
    isClearMode,
    showAddDialog,
    showEditDialog,
    showDayDetailDialog,
    showEventsManageDialog,
    showSchemaConfigDialog,
    searchKeyword,
    filteredEvents,
    selectedDayInfo,
    newEventForm,
    editEventForm,
    events,
    dayEvents,
    eventCounts,
    getEventCount,
    predefineColors,
    fieldSchema,
    updateFieldSchema,
    toggleEditMode,
    toggleClearMode,
    handleEventClick,
    handleManageEventClick,
    addEvent,
    saveEditEvent,
    confirmDeleteEvent,
    changeYear,
    enterMonth,
    exitMonth,
    getMonthDays,
    hasColor,
    getDayEventNames,
    getMonthEventTypes,
    getMonthEventCount,
    getTotalEventTypes,
    getTotalEventCount,
    getYearEventCount,
    getDayStyle,
    toggleDayEvent,
    exportData,
    importData
  }
}
