<template>
  <el-dialog
    :model-value="modelValue"
    :title="title"
    width="420px"
    @update:model-value="emit('update:modelValue', $event)"
  >
    <el-form :model="localForm" label-width="80px" class="event-form">
      <template v-for="field in fieldSchema" :key="field.id">
        <el-form-item :label="field.label" :required="field.required">
          <!-- 短文本 -->
          <el-input
            v-if="field.type === 'text'"
            v-model="localForm[field.key]"
            :placeholder="`请输入${field.label}`"
          />

          <!-- 限长文本 -->
          <el-input
            v-else-if="field.type === 'text-limited'"
            v-model="localForm[field.key]"
            :maxlength="field.maxLength"
            :show-word-limit="!!field.maxLength"
            :placeholder="field.hint || `请输入${field.label}`"
          />

          <!-- 颜色 -->
          <div v-else-if="field.type === 'color'" class="color-picker-row">
            <el-color-picker
              v-model="localForm[field.key]"
              :predefine="predefineColors"
            />
            <span
              v-if="localForm[field.key]"
              class="color-preview-text"
              :style="{ color: localForm[field.key] }"
            >{{ localForm[field.key] }}</span>
          </div>

          <!-- 长文本 textarea -->
          <el-input
            v-else-if="field.type === 'textarea'"
            v-model="localForm[field.key]"
            type="textarea"
            :rows="4"
            :maxlength="field.maxLength"
            :show-word-limit="!!field.maxLength"
            :placeholder="`请输入${field.label}`"
          />

          <!-- 开关 -->
          <el-switch
            v-else-if="field.type === 'switch'"
            v-model="localForm[field.key]"
            :active-text="field.activeText"
            :inactive-text="field.inactiveText"
          />

          <!-- 数字 -->
          <el-input-number
            v-else-if="field.type === 'number'"
            v-model="localForm[field.key]"
            :min="field.min"
            :max="field.max"
            style="width: 160px"
          />

          <!-- 下拉选择 -->
          <el-select
            v-else-if="field.type === 'select'"
            v-model="localForm[field.key]"
            :placeholder="`请选择${field.label}`"
            clearable
            style="width: 100%"
          >
            <el-option
              v-for="opt in (field.options || [])"
              :key="opt"
              :label="opt"
              :value="opt"
            />
          </el-select>

          <!-- 星级评分 -->
          <el-rate
            v-else-if="field.type === 'rating'"
            v-model="localForm[field.key]"
            :max="field.max || 5"
            :allow-half="field.allowHalf"
            style="height: 32px; display: flex; align-items: center"
          />
        </el-form-item>
      </template>
    </el-form>

    <template #footer>
      <el-button @click="emit('update:modelValue', false)">取消</el-button>
      <el-button v-if="isEdit" type="danger" @click="emit('delete', { ...localForm })">删除</el-button>
      <el-button type="primary" @click="emit('confirm', { ...localForm })">
        {{ isEdit ? '保存' : '确定' }}
      </el-button>
    </template>
  </el-dialog>
</template>

<script setup>
import { defineEmits, defineProps, ref, watch } from 'vue'
import { getTypeDefault } from '../composables/useCalendarApp'

const props = defineProps({
  modelValue: { type: Boolean, required: true },
  title:      { type: String, required: true },
  form:       { type: Object, required: true },
  fieldSchema:    { type: Array, required: true },
  predefineColors:{ type: Array, required: true },
  isEdit:     { type: Boolean, default: false }
})

const emit = defineEmits(['update:modelValue', 'confirm', 'delete'])

const localForm = ref({})

watch(
  () => [props.modelValue, props.form, props.fieldSchema],
  () => {
    if (!props.modelValue) return
    const form = { id: props.form.id || '' }
    props.fieldSchema.forEach(field => {
      const val = props.form[field.key]
      form[field.key] = val !== undefined ? val : (field.defaultValue !== undefined ? field.defaultValue : getTypeDefault(field.type))
    })
    localForm.value = form
  },
  { immediate: true, deep: true }
)
</script>

<style scoped>
.event-form {
  padding-top: 4px;
}

.color-picker-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.color-preview-text {
  font-size: 12px;
  font-weight: 500;
  opacity: 0.85;
}
</style>
