<template>
  <el-dialog
    :model-value="modelValue"
    :title="dialogTitle"
    width="500px"
    class="day-detail-dialog"
    @update:model-value="emit('update:modelValue', $event)"
  >
    <div class="day-detail-content">
      <div
        v-for="(eventInfo, index) in dayInfo.events"
        :key="eventInfo.id"
        class="event-detail-card"
        :style="{
          backgroundColor: eventInfo.color,
          marginBottom: index < dayInfo.events.length - 1 ? '12px' : '0'
        }"
      >
        <div class="event-card-header">
          <div class="event-card-icon">
            {{ eventInfo.iconText || eventInfo.name.charAt(0) }}
          </div>
          <div class="event-card-title">
            {{ eventInfo.name }}
          </div>
          <div class="event-card-count">
            <img src="../assets/t.png" class="event-card-count-icon" />
            <span>{{ getEventCount(eventInfo.id) }}</span>
          </div>
        </div>

        <!-- Dynamic extra fields (skip system display fields) -->
        <div v-if="extraFields(eventInfo).length" class="event-card-extra">
          <div
            v-for="field in extraFields(eventInfo)"
            :key="field.id"
            class="extra-field-row"
          >
            <span class="extra-field-label">{{ field.label }}</span>
            <span class="extra-field-value">
              <!-- switch -->
              <span v-if="field.type === 'switch'">
                {{ eventInfo[field.key] ? (field.activeText || '是') : (field.inactiveText || '否') }}
              </span>
              <!-- rating -->
              <el-rate
                v-else-if="field.type === 'rating'"
                :model-value="Number(eventInfo[field.key]) || 0"
                :max="field.max || 5"
                :allow-half="field.allowHalf"
                disabled
                size="small"
                style="height: 20px; display: inline-flex; align-items: center"
              />
              <!-- color -->
              <span
                v-else-if="field.type === 'color'"
                class="extra-color-dot"
                :style="{ background: eventInfo[field.key] }"
              />
              <!-- text / number / select / textarea -->
              <span v-else>{{ eventInfo[field.key] }}</span>
            </span>
          </div>
        </div>
      </div>
      <div v-if="dayInfo.events.length === 0" class="no-events">
        暂无
      </div>
    </div>
    <template #footer>
      <el-button @click="emit('update:modelValue', false)">关闭</el-button>
    </template>
  </el-dialog>
</template>

<script setup>
import { computed, defineEmits, defineProps } from 'vue'

const props = defineProps({
  modelValue: { type: Boolean, required: true },
  dayInfo:    { type: Object, required: true },
  getEventCount: { type: Function, required: true },
  fieldSchema: { type: Array, default: () => [] }
})

const emit = defineEmits(['update:modelValue'])

const dialogTitle = computed(() => {
  const { year, month, day } = props.dayInfo
  if (!year) return ''
  return `${year}年${month}月${day}日`
})

const HIDDEN_IN_CARD = new Set(['name', 'iconText', 'color'])

const extraFields = (eventInfo) => {
  return props.fieldSchema.filter(field => {
    if (HIDDEN_IN_CARD.has(field.key)) return false
    const val = eventInfo[field.key]
    if (val === undefined || val === null || val === '') return false
    if (field.type === 'switch' && val === false) return false
    if ((field.type === 'number' || field.type === 'rating') && val === 0) return false
    return true
  })
}
</script>

<style scoped>
.event-card-extra {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.35);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.extra-field-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}

.extra-field-label {
  color: rgba(255, 255, 255, 0.75);
  min-width: 56px;
  flex-shrink: 0;
}

.extra-field-value {
  color: rgba(255, 255, 255, 0.95);
  font-weight: 500;
  word-break: break-all;
}

.extra-color-dot {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.6);
  vertical-align: middle;
}
</style>
