<template>
  <el-dialog
    :model-value="modelValue"
    width="80%"
    class="events-manage-dialog"
    @update:model-value="emit('update:modelValue', $event)"
  >
    <div class="manage-header">
      <el-input
        :model-value="searchKeyword"
        placeholder="搜索"
        clearable
        class="search-input"
        @update:model-value="emit('update:searchKeyword', $event)"
      >
        <template #prefix>
          <el-icon><Search /></el-icon>
        </template>
      </el-input>

      <div class="manage-actions">
        <el-tooltip content="添加" placement="top" effect="dark">
          <div class="action-button" @click="emit('open-add')">
            <el-icon :size="18"><Plus /></el-icon>
          </div>
        </el-tooltip>
        <el-tooltip content="编辑" placement="top" effect="dark">
          <div :class="['action-button', { active: isEditMode }]" @click="emit('toggle-edit')">
            <el-icon :size="18"><Edit /></el-icon>
          </div>
        </el-tooltip>
      </div>
    </div>

    <div class="manage-event-list">
      <el-tooltip
        v-for="event in filteredEvents"
        :key="event.id"
        placement="bottom"
        effect="dark"
      >
        <template #content>
          <div>{{ event.name }}</div>
        </template>
        <div
          :class="['manage-event-circle', { selected: selectedEventId === event.id }]"
          :style="{ backgroundColor: event.color }"
          @click="emit('event-click', event.id)"
        >
          <span class="manage-event-initial">{{ event.iconText || event.name.charAt(0) }}</span>
          <div v-if="isEditMode" class="manage-edit-badge">
            <el-icon :size="12"><Edit /></el-icon>
          </div>
          <span class="event-count-badge">
            {{ getEventCount(event.id) }}
          </span>
        </div>
      </el-tooltip>
      <div v-if="filteredEvents.length === 0" class="no-events-manage">
        {{ searchKeyword ? '未找到' : '暂无' }}
      </div>
    </div>

    <!-- Statistics panel -->
    <div v-if="events.length > 0" class="stats-panel">
      <div class="stats-panel-header" @click="statsExpanded = !statsExpanded">
        <span class="stats-panel-title">数据统计</span>
        <el-icon class="stats-chevron" :class="{ rotated: statsExpanded }">
          <ArrowDown />
        </el-icon>
      </div>

      <transition name="stats-expand">
        <div v-show="statsExpanded" class="stats-panel-body">
          <!-- Basic stats -->
          <div class="basic-stats-row">
            <div class="stat-chip">
              <span class="sc-val">{{ events.length }}</span>
              <span class="sc-label">事件种类</span>
            </div>
            <div class="stat-chip">
              <span class="sc-val">{{ avgEventCount }}</span>
              <span class="sc-label">平均次数</span>
            </div>
            <div class="stat-chip">
              <span class="sc-val">{{ totalEventCount }}</span>
              <span class="sc-label">累计次数</span>
            </div>
          </div>

          <!-- Field stats -->
          <template v-if="computedFieldStats.length > 0">
            <div class="field-stats-list">
              <!-- avg (number / rating) -->
              <div
                v-for="stat in computedFieldStats.filter(s => s.type === 'avg')"
                :key="stat.field.id"
                class="fstat-row fstat-avg"
              >
                <span class="fstat-label">
                  <span :class="['fstat-type-dot', `dot-${stat.field.type}`]"></span>
                  {{ stat.field.label }}
                </span>
                <div class="fstat-avg-body">
                  <span class="fstat-avg-val">
                    {{ stat.avg }}<span v-if="stat.field.type === 'rating'" class="fstat-unit">★</span>
                  </span>
                  <span class="fstat-meta">均值 · {{ stat.count }} 个</span>
                  <div v-if="stat.field.type === 'rating'" class="rating-bar-track">
                    <div
                      class="rating-bar-fill"
                      :style="{ width: (Number(stat.avg) / (stat.field.max || 5) * 100) + '%' }"
                    ></div>
                  </div>
                </div>
              </div>

              <!-- switch -->
              <div
                v-for="stat in computedFieldStats.filter(s => s.type === 'switch')"
                :key="stat.field.id"
                class="fstat-row fstat-switch"
              >
                <span class="fstat-label">
                  <span class="fstat-type-dot dot-switch"></span>
                  {{ stat.field.label }}
                </span>
                <div class="switch-stat-body">
                  <div class="sw-segment sw-on">
                    <span class="sw-lbl">{{ stat.onLabel }}</span>
                    <div class="sw-bar-track">
                      <div
                        class="sw-bar-fill sw-fill-on"
                        :style="{ width: stat.total ? (stat.onCount / stat.total * 100) + '%' : '0%' }"
                      ></div>
                    </div>
                    <span class="sw-cnt">{{ stat.onCount }}</span>
                  </div>
                  <div class="sw-segment sw-off">
                    <span class="sw-lbl">{{ stat.offLabel }}</span>
                    <div class="sw-bar-track">
                      <div
                        class="sw-bar-fill sw-fill-off"
                        :style="{ width: stat.total ? (stat.offCount / stat.total * 100) + '%' : '0%' }"
                      ></div>
                    </div>
                    <span class="sw-cnt">{{ stat.offCount }}</span>
                  </div>
                </div>
              </div>

              <!-- select distribution -->
              <div
                v-for="stat in computedFieldStats.filter(s => s.type === 'distribution')"
                :key="stat.field.id"
                class="fstat-row fstat-select"
              >
                <span class="fstat-label">
                  <span class="fstat-type-dot dot-select"></span>
                  {{ stat.field.label }}
                </span>
                <div class="dist-list">
                  <div v-for="item in stat.items" :key="item.opt" class="dist-row">
                    <span class="dist-opt">{{ item.opt }}</span>
                    <div class="dist-track">
                      <div
                        class="dist-fill"
                        :style="{ width: item.pct + '%' }"
                      ></div>
                    </div>
                    <span class="dist-cnt">{{ item.count }}</span>
                  </div>
                </div>
              </div>
            </div>
          </template>

          <div v-else class="no-field-stats">
            在「属性配置」中为数字、评分、开关或下拉选择开启「纳入统计」可见更多
          </div>
        </div>
      </transition>
    </div>

    <template #footer>
      <el-button @click="emit('update:modelValue', false)">关闭</el-button>
    </template>
  </el-dialog>
</template>

<script setup>
import { computed, defineEmits, defineProps, ref } from 'vue'
import { ArrowDown, Edit, Plus, Search } from '@element-plus/icons-vue'

const props = defineProps({
  modelValue:      { type: Boolean, required: true },
  searchKeyword:   { type: String,  required: true },
  filteredEvents:  { type: Array,   required: true },
  events:          { type: Array,   required: true },
  fieldSchema:     { type: Array,   default: () => [] },
  isEditMode:      { type: Boolean, required: true },
  selectedEventId: { type: String,  default: null },
  getEventCount:   { type: Function, required: true }
})

const emit = defineEmits([
  'update:modelValue',
  'update:searchKeyword',
  'open-add',
  'toggle-edit',
  'event-click'
])

const statsExpanded = ref(true)

/* ── Basic stats ── */
const totalEventCount = computed(() =>
  props.events.reduce((sum, e) => sum + props.getEventCount(e.id), 0)
)

const avgEventCount = computed(() => {
  if (!props.events.length) return '0'
  return (totalEventCount.value / props.events.length).toFixed(1)
})

/* ── Field stats ── */
const computedFieldStats = computed(() => {
  const statsFields = props.fieldSchema.filter(
    f => ['number', 'rating', 'select', 'switch'].includes(f.type) && f.includeInStats
  )

  return statsFields.map(field => {
    const evts = props.events

    if (field.type === 'number' || field.type === 'rating') {
      const vals = evts
        .map(e => e[field.key])
        .filter(v => v !== undefined && v !== null && Number(v) !== 0)
        .map(Number)
        .filter(v => !isNaN(v))
      if (!vals.length) return null
      const avg = (vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(1)
      return { type: 'avg', field, avg, count: vals.length }
    }

    if (field.type === 'select') {
      const counts = {}
      ;(field.options || []).forEach(opt => { counts[opt] = 0 })
      evts.forEach(e => {
        const val = e[field.key]
        if (val) counts[val] = (counts[val] || 0) + 1
      })
      const max = Math.max(...Object.values(counts), 1)
      const items = Object.entries(counts)
        .map(([opt, count]) => ({ opt, count, pct: Math.round((count / max) * 100) }))
        .sort((a, b) => b.count - a.count)
      return { type: 'distribution', field, items }
    }

    if (field.type === 'switch') {
      const onCount = evts.filter(e => e[field.key] === true).length
      const offCount = evts.length - onCount
      return {
        type: 'switch', field,
        onCount, offCount,
        total: evts.length,
        onLabel: field.activeText || '是',
        offLabel: field.inactiveText || '否'
      }
    }

    return null
  }).filter(Boolean)
})
</script>

<style scoped>
/* ── Stats panel wrapper ─────────────────────── */
.stats-panel {
  margin-top: 14px;
  border: 1.5px solid #e8dfc8;
  border-radius: 10px;
  overflow: hidden;
}

.stats-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  background: #f5f0e8;
  cursor: pointer;
  user-select: none;
  transition: background 0.15s;
}

.stats-panel-header:hover {
  background: #ede5d3;
}

.stats-panel-title {
  font-size: 13px;
  font-weight: 600;
  color: #5d4e37;
}

.stats-chevron {
  color: #8f7955;
  font-size: 13px;
  transition: transform 0.22s;
}

.stats-chevron.rotated {
  transform: rotate(180deg);
}

.stats-panel-body {
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: #fffdf8;
}

/* ── Basic stats chips ───────────────────────── */
.basic-stats-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.stat-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 72px;
  padding: 8px 14px;
  background: #fff;
  border: 1.5px solid #e8dfc8;
  border-radius: 8px;
  gap: 2px;
}

.sc-val {
  font-size: 22px;
  font-weight: 700;
  color: #5d4e37;
  line-height: 1.2;
}

.sc-label {
  font-size: 11px;
  color: #a08c70;
}

/* ── Field stats list ────────────────────────── */
.field-stats-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.fstat-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.fstat-label {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 600;
  color: #5d4e37;
  min-width: 80px;
  padding-top: 3px;
  flex-shrink: 0;
}

.fstat-type-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dot-number  { background: #d44b7a; }
.dot-rating  { background: #c89c00; }
.dot-switch  { background: #3a9a3a; }
.dot-select  { background: #8a8a3a; }

/* ── Avg (number / rating) ───────────────────── */
.fstat-avg-body {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.fstat-avg-val {
  font-size: 20px;
  font-weight: 700;
  color: #5d4e37;
  line-height: 1;
}

.fstat-unit {
  font-size: 14px;
  color: #c89c00;
  margin-left: 1px;
}

.fstat-meta {
  font-size: 11px;
  color: #a08c70;
}

.rating-bar-track {
  flex: 1;
  min-width: 60px;
  max-width: 160px;
  height: 6px;
  background: #e8dfc8;
  border-radius: 3px;
  overflow: hidden;
}

.rating-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #c4a97d, #8f7955);
  border-radius: 3px;
  transition: width 0.4s ease;
}

/* ── Switch ──────────────────────────────────── */
.switch-stat-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.sw-segment {
  display: flex;
  align-items: center;
  gap: 7px;
}

.sw-lbl {
  font-size: 11px;
  color: #7a6a55;
  width: 22px;
  flex-shrink: 0;
}

.sw-bar-track {
  flex: 1;
  max-width: 160px;
  height: 6px;
  background: #e8dfc8;
  border-radius: 3px;
  overflow: hidden;
}

.sw-bar-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.4s ease;
}

.sw-fill-on  { background: #3a9a3a; }
.sw-fill-off { background: #b0a090; }

.sw-cnt {
  font-size: 12px;
  font-weight: 600;
  color: #5d4e37;
  min-width: 18px;
  text-align: right;
}

/* ── Select distribution ─────────────────────── */
.fstat-select {
  align-items: flex-start;
}

.dist-list {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.dist-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.dist-opt {
  font-size: 11px;
  color: #7a6a55;
  min-width: 40px;
  max-width: 80px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dist-track {
  flex: 1;
  max-width: 160px;
  height: 6px;
  background: #e8dfc8;
  border-radius: 3px;
  overflow: hidden;
}

.dist-fill {
  height: 100%;
  background: linear-gradient(90deg, #c4a97d, #8f7955);
  border-radius: 3px;
  transition: width 0.4s ease;
}

.dist-cnt {
  font-size: 12px;
  font-weight: 600;
  color: #5d4e37;
  min-width: 18px;
  text-align: right;
}

/* ── No field stats hint ─────────────────────── */
.no-field-stats {
  font-size: 12px;
  color: #b0a090;
  text-align: center;
  padding: 4px 0 2px;
}

/* ── Transition ──────────────────────────────── */
.stats-expand-enter-active,
.stats-expand-leave-active {
  transition: opacity 0.2s, max-height 0.25s ease;
  max-height: 600px;
  overflow: hidden;
}

.stats-expand-enter-from,
.stats-expand-leave-to {
  opacity: 0;
  max-height: 0;
}
</style>
