<template>
  <el-dialog
    :model-value="modelValue"
    title="事件属性配置"
    width="520px"
    class="schema-config-dialog"
    @update:model-value="onDialogChange"
    @open="onOpen"
  >
    <div class="schema-body">
      <!-- Field list -->
      <div class="field-list">
        <div
          v-for="(field, index) in localSchema"
          :key="field.id"
          :class="['field-item', { 'is-system': field.system, 'is-editing': editingIndex === index }]"
        >
          <span class="field-lock" :title="field.system ? '系统字段' : ''">
            {{ field.system ? '🔒' : '' }}
          </span>
          <span class="field-label-text">{{ field.label }}</span>
          <span :class="['type-badge', `type-${field.type}`]">{{ typeLabel(field) }}</span>
          <span v-if="field.required" class="required-dot" title="必填">●</span>
          <div class="field-item-actions">
            <button class="icon-btn" title="上移" :disabled="index === 0" @click="moveField(index, -1)">↑</button>
            <button class="icon-btn" title="下移" :disabled="index === localSchema.length - 1" @click="moveField(index, 1)">↓</button>
            <button class="icon-btn edit-btn" title="编辑" @click="startEdit(field, index)">✏</button>
            <button class="icon-btn delete-btn" title="删除" :disabled="field.system" @click="deleteField(index)">✕</button>
          </div>
        </div>
        <div v-if="localSchema.length === 0" class="no-fields">暂无字段</div>
      </div>

      <button class="add-field-btn" @click="startAdd">＋ 添加字段</button>

      <!-- Field editor -->
      <transition name="editor-slide">
        <div v-if="editingField" class="field-editor">
          <div class="editor-title">{{ isAdding ? '添加字段' : '编辑字段' }}</div>

          <div class="editor-form">
            <div class="form-row">
              <label class="form-label">字段名称 <span class="required-mark">*</span></label>
              <el-input
                v-model="editingField.label"
                placeholder="显示名称，如：重要程度"
                size="small"
              />
            </div>

            <div class="form-row">
              <label class="form-label">字段类型</label>
              <el-select
                v-model="editingField.type"
                size="small"
                :disabled="editingField.system"
                @change="onTypeChange"
              >
                <el-option
                  v-for="t in fieldTypes"
                  :key="t.value"
                  :label="t.label"
                  :value="t.value"
                >
                  <span class="type-opt-icon">{{ t.icon }}</span>
                  <span class="type-opt-label">{{ t.label }}</span>
                  <span class="type-opt-desc">{{ t.desc }}</span>
                </el-option>
              </el-select>
            </div>

            <div class="form-row">
              <label class="form-label">必填</label>
              <el-switch v-model="editingField.required" size="small" />
            </div>

            <!-- text-limited -->
            <template v-if="editingField.type === 'text-limited'">
              <div class="form-row">
                <label class="form-label">最大字数</label>
                <el-input-number
                  v-model="editingField.maxLength"
                  :min="1"
                  :max="500"
                  size="small"
                  style="width: 120px"
                />
              </div>
            </template>

            <!-- textarea -->
            <template v-if="editingField.type === 'textarea'">
              <div class="form-row">
                <label class="form-label">最大字数</label>
                <el-input-number
                  v-model="editingField.maxLength"
                  :min="10"
                  :max="10000"
                  size="small"
                  style="width: 120px"
                />
              </div>
            </template>

            <!-- color -->
            <template v-if="editingField.type === 'color'">
              <div class="form-row">
                <label class="form-label">默认颜色</label>
                <el-color-picker
                  v-model="editingField.defaultValue"
                  :predefine="predefineColors"
                  size="small"
                />
              </div>
            </template>

            <!-- switch -->
            <template v-if="editingField.type === 'switch'">
              <div class="form-row">
                <label class="form-label">默认值</label>
                <el-switch v-model="editingField.defaultValue" size="small" />
              </div>
              <div class="form-row two-col">
                <div class="form-col">
                  <label class="form-label">开启文字</label>
                  <el-input
                    v-model="editingField.activeText"
                    placeholder="如：是"
                    maxlength="4"
                    size="small"
                  />
                </div>
                <div class="form-col">
                  <label class="form-label">关闭文字</label>
                  <el-input
                    v-model="editingField.inactiveText"
                    placeholder="如：否"
                    maxlength="4"
                    size="small"
                  />
                </div>
              </div>
            </template>

            <!-- number -->
            <template v-if="editingField.type === 'number'">
              <div class="form-row two-col">
                <div class="form-col">
                  <label class="form-label">最小值</label>
                  <el-input-number
                    v-model="editingField.min"
                    size="small"
                    style="width: 100%"
                  />
                </div>
                <div class="form-col">
                  <label class="form-label">最大值</label>
                  <el-input-number
                    v-model="editingField.max"
                    size="small"
                    style="width: 100%"
                  />
                </div>
              </div>
              <div class="form-row">
                <label class="form-label">默认值</label>
                <el-input-number
                  v-model="editingField.defaultValue"
                  :min="editingField.min"
                  :max="editingField.max"
                  size="small"
                  style="width: 120px"
                />
              </div>
            </template>

            <!-- select -->
            <template v-if="editingField.type === 'select'">
              <div class="form-row col-layout">
                <label class="form-label">选项列表</label>
                <div class="options-list">
                  <div
                    v-for="(opt, i) in editingField.options"
                    :key="i"
                    class="option-item"
                  >
                    <el-input
                      v-model="editingField.options[i]"
                      size="small"
                      placeholder="选项文字"
                    />
                    <button class="icon-btn delete-btn" @click="editingField.options.splice(i, 1)">✕</button>
                  </div>
                  <button class="add-option-btn" @click="editingField.options.push('')">＋ 添加选项</button>
                </div>
              </div>
            </template>

            <!-- rating -->
            <template v-if="editingField.type === 'rating'">
              <div class="form-row two-col">
                <div class="form-col">
                  <label class="form-label">最大星数</label>
                  <el-input-number
                    v-model="editingField.max"
                    :min="3"
                    :max="10"
                    size="small"
                    style="width: 100%"
                  />
                </div>
                <div class="form-col">
                  <label class="form-label">允许半星</label>
                  <el-switch v-model="editingField.allowHalf" size="small" />
                </div>
              </div>
              <div class="form-row">
                <label class="form-label">默认值</label>
                <el-rate
                  v-model="editingField.defaultValue"
                  :max="editingField.max || 5"
                  :allow-half="editingField.allowHalf"
                  size="small"
                />
              </div>
            </template>

            <!-- includeInStats — for number / rating / select / switch -->
            <template v-if="STATS_TYPES.includes(editingField.type)">
              <div class="form-row include-stats-row">
                <label class="form-label">纳入统计</label>
                <el-switch v-model="editingField.includeInStats" size="small" />
                <span class="include-stats-hint">开启后在事件列表可查看聚合统计</span>
              </div>
            </template>
          </div>

          <div class="editor-actions">
            <el-button size="small" @click="cancelEdit">取消</el-button>
            <el-button size="small" type="primary" @click="confirmEdit">
              {{ isAdding ? '添加' : '保存' }}
            </el-button>
          </div>
        </div>
      </transition>
    </div>

    <template #footer>
      <el-button @click="onDialogChange(false)">取消</el-button>
      <el-button type="primary" @click="save">保存配置</el-button>
    </template>
  </el-dialog>
</template>

<script setup>
import { computed, defineEmits, defineProps, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'

const props = defineProps({
  modelValue: { type: Boolean, required: true },
  fieldSchema: { type: Array, required: true }
})

const emit = defineEmits(['update:modelValue', 'save'])

const predefineColors = [
  '#ff4500', '#ff8c00', '#ffd700', '#90ee90', '#00ced1',
  '#1e90ff', '#c71585', '#ff69b4', '#ba55d3', '#9370db',
  '#3cb371', '#b8860b', '#cd5c5c', '#4682b4', '#8f7955'
]

const fieldTypes = [
  { value: 'text',         label: '短文本',   icon: 'T',  desc: '单行文本' },
  { value: 'text-limited', label: '限长文本', icon: 'T₀', desc: '带字数上限的单行文本' },
  { value: 'color',        label: '颜色',     icon: '◉',  desc: '颜色选择器' },
  { value: 'textarea',     label: '长文本',   icon: '≡',  desc: '多行文本，可设字数上限' },
  { value: 'switch',       label: '开关',     icon: '◐',  desc: '是 / 否 切换' },
  { value: 'number',       label: '数字',     icon: '#',  desc: '数字输入，可设范围' },
  { value: 'select',       label: '下拉选择', icon: '▽',  desc: '从预设选项中选择' },
  { value: 'rating',       label: '星级评分', icon: '★',  desc: '1～N 星评分' }
]

const typeLabels = {
  'text':         '短文本',
  'text-limited': '限长文本',
  'color':        '颜色',
  'textarea':     '长文本',
  'switch':       '开关',
  'number':       '数字',
  'select':       '下拉',
  'rating':       '评分'
}

const localSchema = ref([])
const editingField = ref(null)
const editingIndex = ref(-1)

const isAdding = computed(() => editingIndex.value === -1)

const typeLabel = (field) => {
  const base = typeLabels[field.type] || field.type
  if ((field.type === 'text-limited' || field.type === 'textarea') && field.maxLength) {
    return `${base} ≤${field.maxLength}`
  }
  if (field.type === 'rating' && field.max) {
    return `${base} ${field.max}★`
  }
  return base
}

const onOpen = () => {
  localSchema.value = JSON.parse(JSON.stringify(props.fieldSchema))
  editingField.value = null
  editingIndex.value = -1
}

watch(() => props.modelValue, (val) => {
  if (val) onOpen()
})

const onDialogChange = (val) => {
  if (!val) {
    editingField.value = null
    editingIndex.value = -1
  }
  emit('update:modelValue', val)
}

const STATS_TYPES = ['number', 'rating', 'select', 'switch']

const getTypeDefaults = (type) => {
  const map = {
    'text':         { defaultValue: '' },
    'text-limited': { defaultValue: '', maxLength: 50 },
    'color':        { defaultValue: '#8f7955' },
    'textarea':     { defaultValue: '', maxLength: 500 },
    'switch':       { defaultValue: false, activeText: '是', inactiveText: '否', includeInStats: true },
    'number':       { defaultValue: 0, min: 0, max: 100, includeInStats: true },
    'select':       { defaultValue: '', options: ['选项1', '选项2'], includeInStats: true },
    'rating':       { defaultValue: 0, max: 5, allowHalf: false, includeInStats: true }
  }
  return map[type] || { defaultValue: '' }
}

const onTypeChange = (newType) => {
  const field = editingField.value
  const keep = { id: field.id, key: field.key, label: field.label, required: field.required, system: field.system, type: newType }
  const defaults = getTypeDefaults(newType)
  editingField.value = { ...keep, ...defaults }
}

const startAdd = () => {
  const id = Date.now().toString()
  editingField.value = {
    id,
    key: `f_${id}`,
    label: '',
    type: 'text',
    required: false,
    system: false,
    defaultValue: ''
  }
  editingIndex.value = -1
}

const startEdit = (field, index) => {
  editingField.value = JSON.parse(JSON.stringify(field))
  editingIndex.value = index
}

const confirmEdit = () => {
  if (!editingField.value.label.trim()) {
    ElMessage.warning('请输入字段名称')
    return
  }
  if (isAdding.value) {
    localSchema.value.push({ ...editingField.value })
  } else {
    localSchema.value[editingIndex.value] = { ...editingField.value }
  }
  editingField.value = null
  editingIndex.value = -1
}

const cancelEdit = () => {
  editingField.value = null
  editingIndex.value = -1
}

const deleteField = (index) => {
  if (editingIndex.value === index) cancelEdit()
  localSchema.value.splice(index, 1)
}

const moveField = (index, dir) => {
  const newIndex = index + dir
  if (newIndex < 0 || newIndex >= localSchema.value.length) return
  const arr = localSchema.value
  ;[arr[index], arr[newIndex]] = [arr[newIndex], arr[index]]
  if (editingIndex.value === index) editingIndex.value = newIndex
  else if (editingIndex.value === newIndex) editingIndex.value = index
}

const save = () => {
  emit('save', JSON.parse(JSON.stringify(localSchema.value)))
  emit('update:modelValue', false)
}
</script>

<style scoped>
.schema-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ─── Field list ─────────────────────────────── */
.field-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 280px;
  overflow-y: auto;
  padding-right: 2px;
}

.field-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border-radius: 8px;
  background: #faf6ef;
  border: 1.5px solid transparent;
  transition: border-color 0.15s, background 0.15s;
}

.field-item.is-system {
  background: #f5f0e6;
}

.field-item.is-editing {
  border-color: #8f7955;
}

.field-lock {
  font-size: 13px;
  width: 18px;
  flex-shrink: 0;
}

.field-label-text {
  flex: 1;
  font-size: 13px;
  font-weight: 500;
  color: #3e3020;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.required-dot {
  color: #d44b40;
  font-size: 10px;
  flex-shrink: 0;
}

.field-item-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}

.no-fields {
  text-align: center;
  color: #aaa;
  padding: 20px;
  font-size: 13px;
}

/* ─── Type badge ─────────────────────────────── */
.type-badge {
  font-size: 11px;
  padding: 2px 7px;
  border-radius: 10px;
  white-space: nowrap;
  flex-shrink: 0;
  font-weight: 500;
}

.type-text         { background: #e8f0ff; color: #3a7bd5; }
.type-text-limited { background: #f0e8ff; color: #7c4dca; }
.type-color        { background: #fff4e8; color: #c87941; }
.type-textarea     { background: #e8fff5; color: #2da878; }
.type-switch       { background: #e8f8e8; color: #3a9a3a; }
.type-number       { background: #fff0f4; color: #d44b7a; }
.type-select       { background: #f4f4e8; color: #8a8a3a; }
.type-rating       { background: #fffbe8; color: #c89c00; }

/* ─── Icon buttons ───────────────────────────── */
.icon-btn {
  width: 22px;
  height: 22px;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: #8f7955;
  cursor: pointer;
  font-size: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, color 0.15s;
  padding: 0;
}

.icon-btn:hover:not(:disabled) {
  background: #e8dfc8;
  color: #5d4e37;
}

.icon-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.icon-btn.edit-btn:hover:not(:disabled) {
  background: #d8e8ff;
  color: #3a7bd5;
}

.icon-btn.delete-btn:hover:not(:disabled) {
  background: #ffe8e8;
  color: #c0392b;
}

/* ─── Add button ─────────────────────────────── */
.add-field-btn {
  align-self: flex-start;
  padding: 5px 14px;
  border: 1.5px dashed #c4b898;
  border-radius: 8px;
  background: transparent;
  color: #8f7955;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.15s;
}

.add-field-btn:hover {
  background: #f5f0e6;
  border-color: #8f7955;
  color: #5d4e37;
}

/* ─── Field editor ───────────────────────────── */
.field-editor {
  border-top: 1.5px solid #e8dfc8;
  padding-top: 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.editor-title {
  font-size: 13px;
  font-weight: 600;
  color: #5d4e37;
}

.editor-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.form-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.form-row.two-col {
  align-items: flex-start;
}

.form-row.col-layout {
  align-items: flex-start;
}

.form-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.form-label {
  font-size: 12px;
  color: #7a6a55;
  width: 72px;
  flex-shrink: 0;
  padding-top: 2px;
}

.required-mark {
  color: #d44b40;
}

/* ─── Select type options ────────────────────── */
.options-list {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.option-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.add-option-btn {
  align-self: flex-start;
  padding: 3px 10px;
  border: 1px dashed #c4b898;
  border-radius: 6px;
  background: transparent;
  color: #8f7955;
  font-size: 12px;
  cursor: pointer;
  margin-top: 2px;
}

.add-option-btn:hover {
  background: #f5f0e6;
}

/* ─── Editor actions ─────────────────────────── */
.editor-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

/* ─── Type option in select ──────────────────── */
.type-opt-icon {
  display: inline-block;
  width: 20px;
  font-size: 13px;
  color: #8f7955;
}

.type-opt-label {
  font-size: 13px;
  color: #3e3020;
  margin-right: 6px;
}

.type-opt-desc {
  font-size: 11px;
  color: #aaa;
}

/* ─── Include-in-stats row ───────────────────── */
.include-stats-row {
  background: #f5f0e8;
  border-radius: 6px;
  padding: 6px 8px;
  margin-top: 2px;
}

.include-stats-hint {
  font-size: 11px;
  color: #a08c70;
  margin-left: 6px;
}

/* ─── Transition ─────────────────────────────── */
.editor-slide-enter-active,
.editor-slide-leave-active {
  transition: opacity 0.2s, transform 0.2s;
}

.editor-slide-enter-from,
.editor-slide-leave-to {
  opacity: 0;
  transform: translateY(-6px);
}
</style>
