<template>
  <div class="year-view">
    <div
      v-for="month in 12"
      :key="month"
      class="month-card"
      @click="emit('enter-month', month)"
    >
      <div class="month-header-row">
        <div class="month-header">{{ month }}月</div>
        <div class="month-stats">
          <div class="stat-item">
            <img src="../assets/p.png" class="stat-icon">
            <span class="stat-text">{{ getMonthEventTypes(currentYear, month) }}</span>
          </div>
          <div class="stat-item">
            <img src="../assets/t.png" class="stat-icon">
            <span class="stat-text">{{ getMonthEventCount(currentYear, month) }}</span>
          </div>
        </div>
      </div>
      <div class="mini-calendar">
        <div class="weekdays">
          <div v-for="day in weekdays" :key="day" class="weekday">
            {{ day }}
          </div>
        </div>
        <div class="days">
          <div
            v-for="(day, index) in getMonthDays(month)"
            :key="index"
            :class="['day-cell', { empty: !day, colored: day && hasColor(currentYear, month, day) }]"
            :style="day ? getDayStyle(currentYear, month, day) : {}"
          >
            {{ day || '' }}
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { defineEmits, defineProps } from 'vue'

const weekdays = ['日', '一', '二', '三', '四', '五', '六']

defineProps({
  currentYear: {
    type: Number,
    required: true
  },
  getMonthDays: {
    type: Function,
    required: true
  },
  hasColor: {
    type: Function,
    required: true
  },
  getDayStyle: {
    type: Function,
    required: true
  },
  getMonthEventTypes: {
    type: Function,
    required: true
  },
  getMonthEventCount: {
    type: Function,
    required: true
  }
})

const emit = defineEmits(['enter-month'])
</script>
